```python
"""Seed genome: the live ladder policy style-gconv1 (v23, policies/candidates/style-gconv1.policy) as genes.

The policy is a rule pile run top to bottom, ending the turn at the first rule that acts. Here:
- update() picks this turn's rule once (rule(): the highest-priority rule whose condition holds; each
  rule's priority is a constant in rule(), so reordering rules is a constant change) and keeps its
  goal tile and target tile;
- score(o) values each legal option under that rule (r_* genes are conditions; act_value, cast_value
  and shop_value value the options by kind), plus two non-terminal parts that run before it as in the
  policy: shopping on spawn and the cast-ahead at a close enemy champion.
Every hypothesis block the policy used (in_danger, threat_eta, altar_eta, group_threat, closest,
move_towards, dash_towards, ...) is an ordinary gene below, written from SDK reads.

Where it differs from the policy:
- conditions are read once at the start of the turn (update); the policy reads a few of them after its
  own earlier actions that turn (e.g. the fight target after the cast-ahead), and buys the lock before
  its lock-placement check (here a lock bought this turn is placed next turn at the earliest);
- shared byte 7 (lock bought / placed) is written in update(), before the purchase, when the purchase
  will go through; byte 6 (set_team_target) is not written: nothing in the policy reads it;
- shards are bought in powers of two (BUY counts), the same totals per kind;
- every action is an option of the loop, tried once per turn; a refused one is not retried that turn.
"""

RULE: Num = 0           # this turn's rule (ids in rule())
GOAL: Tile = None       # where this turn's rule walks (or dashes)
TGT: Tile = None        # the altar / unit tile this turn's rule acts on
LOCK_BUY: Bool = False  # buy the team's altar lock this turn
SHOP_GOLD: Num = 0      # gold left for shards after the lock
MAPPED: Bool = False    # the static sets below are computed (once per game)
ALTAR_RING: Tiles = None
SAFE_RING: Tiles = None
MONO_GROUPS: Tiles = None
TERRAIN: Tiles = None   # walls, holes, altars, enemy spawn
CAMP_BASE: Tiles = None # camp spawns outside monolith/golem groups
BIG_CAMPS: Tiles = None # monolith and golem spawns
SK0: Num = 0            # ability kind of slot 0
SK1: Num = 0            # ability kind of slot 1
BLOCK: Tiles = None     # this turn: tiles I cannot step onto (computed at turn start)
FIELD: Field = None     # this turn: walking field to GOAL, out to my tile
OPEN: Bool = False      # this turn: GOAL can be walked to
DASH_FREE: Tiles = None
CAMP_T: Tile = None
GEM_MAPPED: Bool = False
GEM_SPAWNS: Tiles = None

@gene("v1", "value of doing this option now")
def score(o: Option) -> Num:
    k = o.kind
    if k == PICK:
        return pick_value(o.champ)
    if k == BUY or k == BUY_LOCK:
        return shop_value(o)
    if shop_pending():
        return 0
    if k == CAST:
        return cast_value(o)
    return act_value(o)

@gene('v3', "option kinds worth listing this pass: only those this turn's rule (or shopping, cast-ahead) can use; dash casts also on the threatened bank walk (rule 11: get the bag to the altar before the chaser)")
def consider(k: Num) -> Bool:
    r = RULE
    if k == PICK:
        return True
    if k == BUY or k == BUY_LOCK:
        return r >= 2 and at_spawn()
    if shop_pending():
        return False
    if k == MOVE:
        return walks()
    if k == CAST:
        return r == 7 or r == 14 or ((r == 3 or r == 11 or r == 20) and dash_gate() and (SK0 == AB_DASH or SK1 == AB_DASH)) or (r >= 3 and ahead_on())
    if k == ATTACK:
        return r == 7 or r == 13 or r == 14 or r == 20
    if k == TRIBUTE:
        return r == 6 or r == 9 or r == 10 or r == 17
    if k == RECALL:
        return r == 4 or r == 5
    if k == LOCK:
        return r == 8
    if k == WARD:
        return r == 20 and here() in bushes() and count_units(enemies()) == 0
    return False

@gene('v2', 'start of turn: block set once, then the rule, its goal and target; free dash middles once per turn; shared-memory and priority writes; a retreating champion acts first next round, fighters before idle allies and the healthiest fighter first; a champion starting a tribute acts early, capture holders after fighters; the camp walk keeps its previous camp tile while that group lives and the tile stays free, unless the new goal is more than 3 tiles nearer; after round 250 the camp walk goes to the nearest live gem-paying group under 300 design strength (set once at round 3) when one exists and is at most 15 tiles farther than the plain camp goal, since gold-only groups add no score; from round 30 the camp walk contests a live gem-paying group an enemy champion is farming (within 2 of it) when it is at most 10 tiles farther than the plain goal')
def update() -> None:
    if not MAPPED:
        ALTAR_RING = altar_ring()
        SAFE_RING = safe_altar_ring()
        MONO_GROUPS = mono_groups()
        TERRAIN = walls() | holes() | altars() | enemy_spawn()
        BIG_CAMPS = type_spawns(MONOLITH) | type_spawns(GOLEM)
        CAMP_BASE = camp_spawns() - BIG_CAMPS - MONO_GROUPS
        SK0 = slot_kind(0)
        SK1 = slot_kind(1)
        MAPPED = True
    if not GEM_MAPPED and round() >= 3:
        GEM_SPAWNS = CAMP_BASE - CAMP_BASE
        for g in range(num_groups()):
            if group_gems(g) > 0 and sum(camp_base_strength(spawn_type(t)) for t in group_tiles(g)) < 300:
                GEM_SPAWNS = GEM_SPAWNS | (group_tiles(g) & CAMP_BASE)
        GEM_MAPPED = True
    BLOCK = blocked_now()
    RULE = rule()
    GOAL = rule_goal()
    TGT = rule_target()
    if RULE == 20 and round() > 250 and valid(GOAL) and size(GEM_SPAWNS) > 0 and not (GOAL in GEM_SPAWNS):
        gt = closest(GEM_SPAWNS - respawning())
        if valid(gt) and dist(here(), gt) <= dist(here(), GOAL) + 15:
            GOAL = gt
    if RULE == 20 and round() > 30 and valid(GOAL) and size(GEM_SPAWNS) > 0:
        hot = ring(enemy_tiles(), 2) & (GEM_SPAWNS - respawning())
        if size(hot) > 0 and not (GOAL in hot):
            gt = closest(hot)
            if valid(gt) and dist(here(), gt) <= dist(here(), GOAL) + 10:
                GOAL = gt
    if RULE == 20:
        if valid(CAMP_T) and valid(GOAL) and CAMP_T != GOAL and not (CAMP_T in respawning()) and not (CAMP_T in ally_tiles()) and not (CAMP_T in enemy_tiles()) and dist(here(), CAMP_T) <= dist(here(), GOAL) + 3:
            GOAL = CAMP_T
        CAMP_T = GOAL
    else:
        CAMP_T = tile(-1, -1)
    OPEN = False
    DASH_FREE = BLOCK & BLOCK
    if walks() and valid(GOAL) and GOAL != here():
        OPEN = walk_open()
        FIELD = walk_field()
        if dash_gate():
            DASH_FREE = dash_mids() - BLOCK
    LOCK_BUY = RULE >= 1 and at_spawn() and wants_lock()
    if LOCK_BUY:
        write_shared(7, read_shared(7) + 2)
    SHOP_GOLD = gold() - (10 if LOCK_BUY else 0)
    if RULE == 8:
        write_shared(7, read_shared(7) + 1)
    if RULE == 20:
        set_priority(1 + rand(149))
    elif RULE == 3:
        set_priority(250)
    elif RULE == 6 or RULE == 9 or RULE == 10 or RULE == 17:
        set_priority(220)
    elif RULE == 7:
        set_priority(150 + floor(me().health_frac * 50))
    elif RULE == 16:
        set_priority(140)

@gene("d1", "draft preference: Vendetta, Vesper Vale, Tavi, Ryth, Ren, then anything")
def pick_value(c: Num) -> Num:
    if c == VENDETTA:
        return 6
    if c == VESPER_VALE:
        return 5
    if c == TAVI:
        return 4
    if c == RYTH:
        return 3
    if c == REN:
        return 2
    return 1

@gene('c0', "this turn's rule: the highest-priority rule whose condition holds (ids 1-20, 20 always holds); bank walks stick to the last turn's bank rule while carrying 5+ gems")
def rule() -> Num:
    top = 0
    pick = 0
    sticky = RULE >= 10 and RULE <= 13 and gems() >= 5
    if 200 > top and r_idle():
        top = 200
        pick = 1
    if 190 > top and r_heal():
        top = 190
        pick = 2
    if 180 > top and r_run():
        top = 180
        pick = 3
    if 175 > top and r_recall():
        top = 175
        pick = 4
    if 170 > top and r_cashout():
        top = 170
        pick = 5
    if 160 > top and r_pass():
        top = 160
        pick = 6
    if 150 > top and r_fight():
        top = 150
        pick = 7
    if 140 > top and r_lock():
        top = 140
        pick = 8
    if 130 > top and r_prefight():
        top = 130
        pick = 9
    if 120 > top and bank_on() and valid(adj_altar()):
        top = 92
        pick = 10
    if 118 > top and bank_on() and threat_near():
        top = 118
        pick = 11
    if 116 > top and bank_on() and bank_blocked():
        top = 116
        pick = 13
    if 114 > top and (bank_on() or sticky):
        top = 114
        pick = 12
    if 100 > top and r_camp():
        top = 100
        pick = 14
    if 90 > top and r_mono():
        top = 90
        pick = 16
    if 80 > top and r_hold():
        top = 80
        pick = 16
    if 70 > top and r_bankgroup() and valid(adj_altar()):
        top = 70
        pick = 17
    if 68 > top and r_bankgroup():
        top = 68
        pick = 18
    if 60 > top and r_live():
        top = 60
        pick = 19
    if 10 > top:
        top = 10
        pick = 20
    return pick

@gene('c1', "where this turn's rule walks (altar walks prefer camp-free altar-adjacent tiles; bank walk keeps its goal while still valid)", parents=["c1"])
def rule_goal() -> Tile:
    r = rule()
    if r == 3:
        return closest(my_spawn())
    if r == 11:
        free = ALTAR_RING - camp_block()
        if size(free) > 0:
            return closest(free)
        return closest(ALTAR_RING)
    if r == 12:
        if valid(GOAL) and GOAL in altar_ring() and not (GOAL in taken()):
            return GOAL
        return bank_goal()
    if r == 15:
        return closest(camp_spawns() - respawning() - type_spawns(GOLEM))
    if r == 18:
        return closest(SAFE_RING)
    if r == 19:
        return live_camp().pos
    if r == 20:
        return camp_goal()
    return tile(-1, -1)

@gene("c2", "the altar or unit tile this turn's rule acts on")
def rule_target() -> Tile:
    r = rule()
    if r == 6 or r == 9 or r == 10 or r == 17:
        return adj_altar()
    if r == 7:
        return fight_foe().pos
    if r == 8:
        return lock_altar()
    if r == 13 or r == 14:
        return reach_camp().pos
    return tile(-1, -1)

@gene("r1", "nothing to do: dead, channeling, or neither move nor attack allowed")
def r_idle() -> Bool:
    return not alive() or channeling() or (not can_move() and not can_attack())

@gene("r2", "heal on spawn: hurt and nothing can be hit from here")
def r_heal() -> Bool:
    return at_spawn() and me().health < me().max_health and not foe_in_reach()

@gene('r3', 'retreat on foot: under fire and below 30% health, or below 45% while carrying 10+ gems (a dead carrier hands its bag to the killer)')
def r_run() -> Bool:
    if at_spawn():
        return False
    lim = 0.45 if gems() >= 10 else 0.3
    return hurt_below(lim) and under_fire()

@gene('r4', 'recall: below 30% health, or below 45% with no enemy champion within 6 and not under fire; never on spawn')
def r_recall() -> Bool:
    if at_spawn():
        return False
    if hurt_below(0.3):
        return True
    return hurt_below(0.45) and enemies_within(6) == 0 and not under_fire()

@gene('r5', 'recall with gems when below half health, or with 10+ gems below 70% health, and nothing near; not when an altar is adjacent or within 4 turns (bank walk instead)')
def r_cashout() -> Bool:
    if at_spawn() or gems() <= 0 or under_fire():
        return False
    if valid(adj_altar()):
        return False
    if altar_eta() <= 4 and hurt_below(0.7029):
        return False
    if gems() >= 10 and hurt_below(0.7):
        return True
    return hurt_below(0.5)

@gene("r6", "pass-through bank: gems, an altar next to us and nothing able to hit us")
def r_pass() -> Bool:
    return gems() > 0 and valid(adj_altar()) and not foe_in_reach()

@gene("r7", "fight the weakest enemy champion in reach (not on its own spawn)")
def r_fight() -> Bool:
    f = fight_foe()
    return exists(f) and dist(here(), f.pos) <= me().attack_range and not (f.pos in enemy_spawn())

@gene("r8", "place the team's altar lock: holder with an empty bag next to an altar, lock not yet placed")
def r_lock() -> Bool:
    v = read_shared(7)
    return gems() == 0 and has_lock() and fuel() > 60000 and v - 2 * floor(v / 2) == 0 and valid(lock_altar())

@gene("r9", "pre-fight bank: 5+ gems, an enemy can reach us within 2 turns, altar next to us")
def r_prefight() -> Bool:
    return gems() >= 5 and threat_eta() <= 1 and valid(adj_altar())

@gene("r10", "bank now: carrying gems and the bag is ready")
def bank_on() -> Bool:
    return gems() > 0 and bag_ready()

@gene("r11", "bag ready: 15+, or 10+ with an altar 3 turns away or a threat near, or late, or hurt (intel: 8+ while the team has banked nothing)", parents=["r11"])
def bag_ready() -> Bool:
    g = gems()
    return g >= 15 or (g >= 10 and altar_eta() <= 3) or (g >= 10 and threat_near()) or round() > 1500 or hurt_below(0.3) or (g >= 8 and team_gems() == 0)

@gene("r12", "threat near: an enemy champion within 5 or able to hit us within 3 turns")
def threat_near() -> Bool:
    return enemies_within(5) > 0 or threat_eta() <= 3

@gene('r13', 'every altar-adjacent tile is a camp spawn and the camp blocking it is in reach: fight the blocker')
def bank_blocked() -> Bool:
    b = bank_t3()
    return not valid(bank_t1()) and not valid(bank_t2()) and b in camp_spawns() and any(in_reach(u) for u in camps() if u.pos == b)

@gene('r14', 'fight the chosen camp in reach; never wake a sleeping monolith unless the monolith rule is on; a sleeping camp of a strong group (240+) is not woken alone below half health (no ally within 6)')
def r_camp() -> Bool:
    c = reach_camp()
    if not exists(c):
        return False
    if not in_reach(c):
        return False
    if c.type == MONOLITH and not is_awake(c) and not r_mono():
        return False
    if not is_awake(c) and hurt_below(0.5) and group_threat(camp_spawn(c)) >= 240:
        return count(dist(a.pos, here()) <= 6 and a.pos != here() for a in allies()) > 0
    return True

@gene('r15', 'monolith push: after round 1000 with 3+ allies, little team gold banked, and healthy')
def r_mono() -> Bool:
    return round() > 1000 and team_gems() < 100 and count_units(allies()) >= 3 and not hurt_below(0.5)

@gene('r16', "standing on a cleared camp group's tile: hold so the capture timer runs, unless the capture is contested (an enemy champion within 3: the timer cannot finish) or an ally with a lower type id already holds the same group (one holder takes the whole reward; extra allies only split it)")
def r_hold() -> Bool:
    p = here()
    g = spawn_group(p)
    if g < 0 or not group_reward(g):
        g = -1
        for k in range(num_groups()):
            if g < 0 and group_reward(k) and p in group_tiles(k):
                g = k
    if g < 0:
        return False
    if any(dist(p, u.pos) <= 3 for u in enemies()):
        return False
    ts = group_tiles(g)
    t = me().type
    return not any(a.pos != p and a.pos in ts and a.type < t for a in allies())

@gene("r17", "bank before a dangerous group: 10+ gems and the next group's strength is 240+")
def r_bankgroup() -> Bool:
    g = camp_goal()
    return valid(g) and gems() >= 10 and group_threat(g) >= 240 and fuel() > 65000

@gene("r18", "on a dead camp of an uncleared group: walk to the nearest living camp (not monolith or golem)")
def r_live() -> Bool:
    c = live_camp()
    return dist(camp_goal(), here()) == 0 and exists(c) and not (c.pos in BIG_CAMPS)

@gene('a0', "value of a move, attack, tribute, recall, lock or ward option under this turn's rule; free hits while holding a capture or retreating, focus the weaker champion")
def act_value(o: Option) -> Num:
    k = o.kind
    r = RULE
    if k == MOVE:
        return move_value(o) if walks() else 0
    if k == ATTACK:
        if r == 7 or r == 14:
            return 178 if o.unit.pos == TGT else 0
        if r == 13:
            return 150 if o.unit.pos == TGT else 0
        u = o.unit
        foe = u.is_enemy and u.is_champion
        if r == 20:
            if u.is_camp:
                return 90 if u.pos == reach_camp().pos else 0
            if foe and in_reach(u):
                return 120 + 20 * (1 - u.health_frac)
            return 0
        if r == 16:
            if foe and in_reach(u):
                return 100 + 20 * (1 - u.health_frac)
            return 0
        if r == 3:
            if foe and in_reach(u):
                return 60 + 20 * (1 - u.health_frac)
            return 0
        return 0
    if k == TRIBUTE:
        return 150 if (r == 6 or r == 9 or r == 10 or r == 17) and o.tile == TGT else 0
    if k == RECALL:
        return 150 if r == 4 or r == 5 else 0
    if k == LOCK:
        return 150 if r == 8 and o.tile == TGT else 0
    if k == WARD:
        return 130 if r == 20 and o.tile == here() and here() in bushes() and count_units(enemies()) == 0 else 0
    return 0

@gene('a1', "this turn's rule walks to GOAL (retreat, bank walks, bank before a dangerous group, monolith walk, live camp, camp walk)")
def walks() -> Bool:
    r = RULE
    return r == 3 or r == 11 or r == 12 or r == 15 or r == 17 or r == 18 or r == 19 or r == 20

@gene('a2', 'value of a cast option: dash on retreat, altar walk and camp walk; a self-heal whenever below 60% health; cast-ahead, casts and resets of a fight; a self-shield or self-heal on the camp walk or a capture hold when below half health and in danger (no solo deaths to a woken group)')
def cast_value(o: Option) -> Num:
    k = SK0 if o.slot == 0 else SK1
    if k == AB_DASH:
        return dash_value(o) if RULE == 3 or RULE == 11 or RULE == 20 else 0
    if k == AB_HEAL and o.unit == me() and me().health_frac < 0.6:
        return 172 - o.slot
    if RULE == 7 or RULE == 14:
        return max(ahead_value(o, k), strike_cast(o, k))
    if (k == AB_SHIELD or k == AB_HEAL) and (RULE == 16 or RULE == 20) and hurt_below(0.5) and in_danger():
        return max(ahead_value(o, k), strike_cast(o, k))
    return ahead_value(o, k)

@gene('a3', 'cast-ahead: damage or stun on a close enemy champion (aoe may land near it); stun a chaser and shield or heal self while retreating or hurt; a damage or stun cast that kills the foe outright (exact damage vs health plus shield) or a stun on a foe channelling a tribute ranks first', parents=['a3'])
def ahead_value(o: Option, k: Num) -> Num:
    if RULE < 3 or RULE == 4 or RULE == 5 or k == AB_RESET:
        return 0
    if not ahead_on():
        return 0
    foe = ahead_foe()
    hit = o.unit.pos if exists(o.unit) else o.tile
    if k == AB_SHIELD or k == AB_HEAL:
        if hit != here():
            return 0
        if RULE == 3 or hurt_below(0.6):
            return 175 - o.slot
        return 0
    if RULE < 6:
        if RULE == 3 and k == AB_CC and not slot_moveless(o.slot) and hit == foe.pos:
            return 185 - o.slot
        return 0
    if hit == foe.pos:
        if (k == AB_DAMAGE or k == AB_CC) and cast_damage(me(), o.slot, foe) >= foe.health + shield(foe):
            return 195 - o.slot
        if k == AB_CC and is_tributing(foe):
            return 192 - o.slot
        return 180 - o.slot
    if k == AB_AOE and dist(hit, foe.pos) <= slot_radius(o.slot):
        return 170 - o.slot - dist(hit, foe.pos)
    return 0

@gene('a4', 'the nearest visible enemy champion, preferring the weaker one at similar range')
def ahead_foe() -> Unit:
    return best(enemies(), lambda u: -dist(here(), u.pos) - 2 * u.health_frac)

@gene("a5", "cast-ahead applies: nearest enemy within 4 and not on its spawn")
def ahead_on() -> Bool:
    f = ahead_foe()
    return exists(f) and dist(here(), f.pos) <= 4 and not (f.pos in enemy_spawn())

@gene('a6', 'fight casts: shield/heal on self when hurt or the slot at TGT first; damage and stun on the fight target by tile or unit; attack resets once the attack is spent')
def strike_cast(o: Option, k: Num) -> Num:
    if k == AB_SHIELD or k == AB_HEAL:
        if o.unit == me():
            return 180 - o.slot if hurt_below(0.5) else 170 - o.slot
        return 0
    if k == AB_RESET:
        return 150 - o.slot if not can_attack() else 0
    if o.tile == TGT:
        return 170 - o.slot
    if exists(o.unit) and o.unit.pos == TGT:
        return 170 - o.slot
    return 0

@gene("a7", "a dash onto the landing tile that brings us closest to GOAL (slot 0 first)")
def dash_value(o: Option) -> Num:
    if not dash_gate():
        return 0
    s = dash_spot()
    return 140 - o.slot if valid(s) and o.tile == s else 0

@gene('a12', 'dash this turn: retreat with fuel > 40k; walks with GOAL over 2 away and fuel > 45k (the walk costs little fuel, the turns saved are worth it)')
def dash_gate() -> Bool:
    if RULE == 3:
        return fuel() > 40000
    return valid(GOAL) and dist(here(), GOAL) > 2 and fuel() > 45000

@gene("a8", "a step downhill on the walking field to GOAL")
def move_value(o: Option) -> Num:
    g = step_gain(o.tile)
    return 100 + g if g > 0 else 0

@gene("a9", "shopping on spawn: the team's altar lock, then shards in the policy's split")
def shop_value(o: Option) -> Num:
    if o.kind == BUY_LOCK:
        return 200 if LOCK_BUY and RULE >= 2 and at_spawn() else 0
    if o.item != next_shard():
        return 0
    if o.count > shard_left() or RULE < 2 or not at_spawn():
        return 0
    return 190 + o.count / 100

@gene('a13', 'a purchase is still due this turn (other options wait, unscored); cheap gold test first')
def shop_pending() -> Bool:
    if gold() < 10:
        return False
    if RULE < 2 or not at_spawn() or not can_shop():
        return False
    if LOCK_BUY and not has_lock():
        return True
    return gold() >= 30 and next_shard() >= 0

@gene('a10', "the team's lock is neither bought nor placed, I have none, it is past round 400 and I can pay with 60 gold to spare (early gold goes to treasure shards and the emblem; ladder locks show no effect on wins)")
def wants_lock() -> Bool:
    if round() < 400 or gold() < 70 or has_lock():
        return False
    v = read_shared(7)
    return floor(v) - 4 * floor(v / 4) == 0

@gene("a11", "next shard to buy: half treasure strength, half the rest jungle health, then power strength/health")
def next_shard() -> Num:
    d = shards_done()
    if d < shard_until(1):
        return 18
    if d < shard_until(2):
        return 28
    if d < shard_until(3):
        return 6
    if d < shard_until(4):
        return 10
    return -1

@gene("a14", "shards bought this turn (30 gold each)")
def shards_done() -> Num:
    return max(0, -floor(-(SHOP_GOLD - gold()) / 30))

@gene('a15', "shards of the first k kinds in the turn's split; before round 400 mostly treasure (4/5), later mostly power strength (bruiser)")
def shard_until(k: Num) -> Num:
    n = floor(SHOP_GOLD / 30)
    if round() < 400:
        t = floor(n * 4 / 5)
        j = floor((n - t) / 2)
        s = floor((n - t - j) / 2)
    else:
        t = floor(n / 4)
        j = floor((n - t) / 4)
        s = floor((n - t - j) * 2 / 3)
    if k == 1:
        return t
    if k == 2:
        return t + j
    if k == 3:
        return t + j + s
    return n

@gene('a16', 'units of the next shard still to buy; treasure shards are capped at what the emblem still needs (5 matching shards), the rest of the gold goes to the next kind')
def shard_left() -> Num:
